'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const Q=new Map(QUESTIONS.map(q=>[q.id,q]));
const T=new Map(TOPICS.map(t=>[t.id,t]));
const chapter=id=>CHAPTERS.find(c=>c.id===Number(id));
let state=Mining.fresh(),storageWarning=false;
try{const saved=localStorage.getItem(Mining.KEY);if(saved)state=Mining.validate(JSON.parse(saved),QUESTIONS,TOPICS);}catch(e){storageWarning=true;}
let route='home',libraryChapter=1,search='',reviewTab='wrong',recallQueue=[],recallIndex=0,recallRevealed=false,recallFilter=0,recallDueOnly=false,toastTimer;
function save(){try{localStorage.setItem(Mining.KEY,JSON.stringify(state));}catch(e){toast('Penyimpanan browser tidak tersedia/penuh. Ekspor progres agar tidak hilang.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V10m6 11v-8h6v8',book:'M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Zm0 0v15',practice:'M9 4h6m-7-1H5v19h14V3h-3M8 10l2 2 5-5M8 17h8',recall:'m12 3-9 11h8l-1 7 11-12h-8l-1-6',review:'M3 11a9 9 0 1 1 3 8M3 4v7h7m2-5v6l4 2',chart:'M4 20V10m8 10V4m8 16v-7',arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bookmark:'M6 3h12v18l-6-4-6 4V3',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',tree:'M12 3v7M5 15v-5h14v5M3 15h4v5H3v-5m14 0h4v5h-4v-5M10 3h4v4h-4V3',table:'M3 4h18v16H3V4m0 5h18M9 4v16m6-16v16M3 14h18',graph:'m6 6 12 2-7 11L6 6m0 0 12 2M8 6a2 2 0 1 1-4 0 2 2 0 0 1 4 0m12 2a2 2 0 1 1-4 0 2 2 0 0 1 4 0m-7 11a2 2 0 1 1-4 0 2 2 0 0 1 4 0',text:'M4 5h16M12 5v15M8 20h8M4 5v3m16-3v3',vision:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12m13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',seed:'M12 21V11m0 4C3 15 2 9 3 4c6 0 9 4 9 9m0-2c0-6 5-8 9-8 0 6-3 10-9 10',layers:'m12 3 10 5-10 5L2 8l10-5M2 12l10 5 10-5M2 16l10 5 10-5',flag:'M5 22V3h13l-3 5 3 5H5',menu:'M4 6h16M4 12h16M4 18h16',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pause:'M8 4v16M16 4v16',play:'m7 3 14 9-14 9V3'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const button=(label,action,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const percent=(a,b)=>b?Math.round(a/b*100):0;
function stats(qs=QUESTIONS){const seen=qs.filter(q=>state.attempts[q.id]),mastered=seen.filter(q=>state.attempts[q.id].lastCorrect);return {seen:seen.length,mastered:mastered.length,pct:percent(mastered.length,qs.length),accuracy:percent(mastered.length,seen.length)};}
function sourceLink(item){const c=chapter(item.chapter),isGCN=item.page.startsWith('GCN'),file=isGCN?'1790064322497_Proses-Detail-dari-GCN.pdf':c.file;const page=Number((item.page.match(/\d+/)||['1'])[0]);return `<a class="source" href="materials/${encodeURIComponent(file)}#page=${page}" target="_blank" rel="noopener">${icon('book')} ${isGCN?'Proses Detail GCN':esc(c.short)} · hlm. ${esc(item.page.replace('GCN ',''))} ↗</a>`;}
function navigate(to){location.hash=to; if(location.hash.slice(1)===to)render();}
function getRoute(){const [r,arg]=location.hash.slice(1).split('/');route=['home','library','practice','session','recall','review','progress'].includes(r)?r:'home';if(route==='library'&&chapter(arg))libraryChapter=Number(arg);}
function shell(){
 const wrong=QUESTIONS.filter(q=>state.attempts[q.id]&&!state.attempts[q.id].lastCorrect).length;
 $('#sidebar').innerHTML=`<a class="brand" href="#home"><span class="brand-symbol">m<span>m</span></span><span>mining mind<small>YOUR LEARNING SPACE</small></span></a><div class="nav-label">RUANG BELAJAR</div><nav>${[['home','Beranda'],['library','Materi belajar'],['practice','Latihan soal'],['recall','Kartu recall'],['review','Ulangi & pahami'],['progress','Progres belajar']].map(([id,label])=>`<a href="#${id}" class="nav-item ${route===id||(route==='session'&&id==='practice')?'active':''}">${icon(id==='library'?'book':id==='progress'?'chart':id)}<span>${label}</span>${id==='review'&&wrong?`<b class="nav-count">${wrong}</b>`:''}</a>`).join('')}</nav><div class="sidebar-note"><span class="eyebrow">SATU LANGKAH SETIAP HARI</span><p>Paham konsepnya.<br>Siap hadapi soalnya.</p><div class="tiny-plant">${icon('seed')}</div></div><div class="sidebar-bottom"><span class="avatar">S</span><div>Ruang belajar pribadi<small>Progres tersimpan di browser ini</small></div></div>`;
 const names={home:'Beranda',library:'Materi belajar',practice:'Latihan soal',session:state.session?.mode==='exam'?'Simulasi ujian':'Sesi latihan',recall:'Kartu recall',review:'Ulangi & pahami',progress:'Progres belajar'};
 $('#topbar').innerHTML=`<div class="breadcrumb">${button(icon('menu'),'menu','icon-btn mobile-menu','aria-label="Buka navigasi"')}<span>Ruang belajar</span><span>/</span><strong>${names[route]}</strong></div><div class="top-actions">${button(icon('clock')+'<span id="focus-label">Fokus 25 menit</span>','focus','focus-btn')}<span class="course-badge">IF4041 <i></i> MIDTERM</span></div>`;
 tick();
}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function network(){return `<svg class="hero-network" viewBox="0 0 330 240" aria-hidden="true"><g fill="none" stroke="#769486" stroke-width="1"><path d="M45 155 115 70 182 120 268 52M45 155l105 48 32-83 99 62-13-130M115 70l35 133 118-151M45 155l137-35 99 62M115 70l153-18M182 120l-6-91M281 182l-1-80"/><circle cx="182" cy="120" r="71" stroke-dasharray="3 5"/><circle cx="182" cy="120" r="101" opacity=".3"/></g><g fill="#d9ee96"><circle cx="45" cy="155" r="7"/><circle cx="115" cy="70" r="10"/><circle cx="150" cy="203" r="6"/><circle cx="268" cy="52" r="7"/><circle cx="281" cy="182" r="10"/><circle cx="176" cy="29" r="4"/><circle cx="280" cy="102" r="4"/><circle cx="182" cy="120" r="26"/></g><path d="m171 119 8 8 14-16" fill="none" stroke="#173e34" stroke-width="3"/><g fill="#bdd0c3" font-family="monospace" font-size="10"><text x="32" y="182">data</text><text x="100" y="50">pattern</text><text x="240" y="213">knowledge</text></g></svg>`;}
function renderHome(){const s=stats(),due=TOPICS.filter(t=>!state.recall[t.id]||state.recall[t.id].due<=Date.now()).length;const weak=CHAPTERS.map(c=>({...c,...stats(QUESTIONS.filter(q=>q.chapter===c.id))})).sort((a,b)=>a.pct-b.pct)[0];
 return `${heading('MIDTERM DATA MINING','Sedikit latihan, <em>banyak pemahaman.</em>','Temukan ritmemu. Kuasai enam bab, satu konsep setiap kali.')}<section class="hero"><div class="hero-copy"><div class="hero-tag"><span></span> RUANG UNTUK BERTUMBUH</div><h2>Dari “pernah baca”<br>jadi “benar-benar paham”.</h2><p>Latihan, ingat kembali, lalu uji dirimu.<br>Semua materi midterm, dalam satu tempat.</p><div class="hero-actions">${button((state.session&&!state.session.done?'Lanjutkan sesi':'Mulai latihan')+icon('arrow'),state.session&&!state.session.done?'resume':'quick-start','btn btn-lime') }<a class="hero-link" href="#library">Jelajahi materi ↗</a></div></div>${network()}<div class="hero-foot">6 BAB <span>·</span> 3 LEVEL <span>·</span> 300 SOAL <span>·</span> 100 KARTU RECALL</div></section>
 <div class="stats-grid"><div class="stat-card"><span>Soal dijelajahi ${icon('practice')}</span><strong>${s.seen}<small> / 300</small></strong><div class="bar"><i style="width:${percent(s.seen,300)}%"></i></div></div><div class="stat-card"><span>Ketepatan terbaru ${icon('chart')}</span><strong>${s.seen?s.accuracy+'%':'—'}</strong><small>${s.mastered} soal benar pada percobaan terakhir</small></div><div class="stat-card"><span>Recall siap diulang ${icon('recall')}</span><strong>${due}<small> kartu</small></strong><small>Bangun ingatan, bukan sekadar hafalan</small></div><div class="stat-card"><span>Ritme belajar ${icon('spark')}</span><strong>${Mining.streak(state)}<small> hari</small></strong><small>Hari berturut dengan latihan tercatat</small></div></div>
 <section><div class="section-head"><div><span class="eyebrow">PETA BELAJARMU</span><h2>Enam bab. Satu tujuan.</h2></div><a class="text-link" href="#library">Lihat semua materi ${icon('arrow')}</a></div><div class="chapter-grid">${CHAPTERS.map(c=>{const cs=stats(QUESTIONS.filter(q=>q.chapter===c.id));return `<a class="chapter-card" href="#library/${c.id}"><div class="chapter-top"><span class="topic-icon ${c.color}">${icon(c.icon)}</span><span class="chapter-num">BAB 0${c.id}</span>${icon('arrow','card-arrow')}</div><h3>${c.title}</h3><p>${c.subtitle}</p><div class="chapter-meta"><span>${TOPICS.filter(t=>t.chapter===c.id).length} konsep · ${QUESTIONS.filter(q=>q.chapter===c.id).length} soal</span><span>${cs.pct}%</span></div><div class="bar"><i style="width:${cs.pct}%"></i></div></a>`;}).join('')}</div></section>
 <section class="bottom-grid"><div class="recommend-card"><span class="topic-icon sage">${icon('seed')}</span><div><span class="eyebrow">LANGKAH KECIL BERIKUTNYA</span><h3>${s.seen?'Perkuat '+weak.short:'Mulai dari fondasi.'}</h3><p>${s.seen?'Coba bab dengan progres terendah, lalu lihat konsep yang perlu diulang.':'Sepuluh soal singkat untuk mengenali apa yang sudah dan belum kamu pahami.'}</p>${button('Latihan 10 soal '+icon('arrow'),'quick-start','text-link')}</div></div><div class="rule-card"><span class="eyebrow">KENALI FORMAT UJIANNYA</span><h3>Satu, beberapa, atau tidak ada.</h3><p>Jawaban benar bisa berjumlah 0–4. Pilih semua yang tepat, atau tandai “Tidak ada jawaban benar”. Nilai diberikan jika seluruh pilihan cocok.</p><a href="#practice" class="text-link">Siapkan sesi latihan ${icon('arrow')}</a></div></section>`;
}
function renderLibrary(){const c=chapter(libraryChapter);let topics=TOPICS.filter(t=>search?`${t.title} ${t.summary} ${chapter(t.chapter).title}`.toLowerCase().includes(search.toLowerCase()):t.chapter===c.id);
 return `${heading('PAHAMI SEBELUM MENGHAFAL','Buka materinya. <em>Hubungkan idenya.</em>','Ringkasan konsep dari slide kuliah Anda, dengan rujukan halaman PDF.')}<div class="toolbar"><label class="search-box">${icon('search')}<input id="search" type="search" placeholder="Cari konsep: GCN, support, LSTM…" value="${esc(search)}" aria-label="Cari seluruh materi"></label><span class="muted">100 konsep · 6 bab</span></div><div class="chapter-tabs">${CHAPTERS.map(ch=>button(`<span>0${ch.id}</span> ${ch.short}`,'chapter','tab '+(!search&&ch.id===c.id?'selected':''),`data-id="${ch.id}"`)).join('')}</div><div class="library-layout"><div><div class="chapter-banner ${c.color}"><span class="topic-icon">${icon(c.icon)}</span><div><span class="eyebrow">${search?'HASIL PENCARIAN':'BAB 0'+c.id}</span><h2>${search?`${topics.length} konsep ditemukan`:c.title}</h2><p>${search?'Hasil dari seluruh bab.':c.sections.join(' · ')}</p></div></div><div class="concept-list">${topics.length?topics.map(t=>`<details class="concept" ${search?'open':''}><summary><span class="concept-number">${String(TOPICS.indexOf(t)+1).padStart(2,'0')}</span><h3>${esc(t.title)}</h3><span class="plus">+</span></summary><div class="concept-body"><p>${esc(t.summary)}</p>${sourceLink(t)}<div class="concept-actions">${button('Latihan konsep ini '+icon('arrow'),'topic-practice','text-link',`data-id="${t.id}"`)}${button('Recall konsep','topic-recall','text-link',`data-id="${t.id}"`)}</div></div></details>`).join(''):empty('Tidak ada konsep yang cocok.','Coba kata kunci yang lebih singkat.')}</div></div><aside class="library-aside"><div class="paper-card"><span class="eyebrow">BELAJAR AKTIF</span><h3>Tutup materinya.<br>Jelaskan dengan bahasamu.</h3><p>Membaca terasa mudah. Mengingat tanpa melihat catatan menunjukkan pemahaman yang sebenarnya.</p>${button('Recall bab ini '+icon('arrow'),'chapter-recall','btn btn-green',`data-id="${c.id}"`)}</div><div class="paper-card"><label for="chapter-note" class="eyebrow">CATATAN PRIBADI · BAB ${c.id}</label><textarea id="chapter-note" rows="8" maxlength="20000" placeholder="Tulis analogi, rumus, atau hal yang sering tertukar…">${esc(state.notes[c.id]||'')}</textarea><small id="note-status" class="muted">Disimpan otomatis di browser ini.</small></div><div class="source-note">${icon('info')}<p>Soal latihan disusun dari materi, bukan soal resmi ujian. Nomor halaman mengacu pada urutan halaman PDF. Catatan istilah menandai penyederhanaan atau perbedaan definisi pada slide.</p></div></aside></div>`;
}
function renderPractice(){return `${heading('LATIH PEMAHAMANMU','Naik level, <em>selangkah demi selangkah.</em>','Pilih tingkat tantangan. Semua level terbuka dan masing-masing berisi tepat 100 soal.')}<div class="mode-note">${icon('info')}<p><strong>Aturan multi-jawaban</strong> · Pilih 0–4 opsi yang benar. Jawaban dinilai tepat jika semua pilihan cocok. Tidak ada pengurangan nilai; skema ini untuk latihan, bukan klaim aturan penilaian dosen.</p></div>${state.session&&!state.session.done?`<div class="resume-banner"><div><strong>Sesi sebelumnya masih tersimpan.</strong><p>${state.session.ids.length} soal · ${state.session.mode==='exam'?'Simulasi ujian':'Latihan'} · ${Object.values(state.session.choices).filter(Array.isArray).length} terisi</p></div>${button('Lanjutkan '+icon('arrow'),'resume','btn btn-green')}</div>`:''}<div class="level-grid">${LEVELS.map(l=>{const st=stats(QUESTIONS.filter(q=>q.level===l.id));return `<article class="level-card level-${l.id}"><div class="level-top"><span class="topic-icon">${icon(l.icon)}</span><span class="eyebrow">LEVEL 0${l.id}</span></div><div class="level-caption">${l.label}</div><h2>${l.name}</h2><p>${l.desc}</p><div class="level-detail"><strong>100 <span>soal unik</span></strong><span>6 bab</span></div><div class="bar"><i style="width:${st.pct}%"></i></div><small>${st.mastered}/100 benar pada percobaan terakhir</small>${button('Mulai level '+l.id+icon('arrow'),'setup','btn btn-green',`data-level="${l.id}" data-mode="practice"`)}</article>`;}).join('')}</div><section class="exam-banner"><div><span class="eyebrow">SAATNYA MENGUJI KESIAPAN</span><h2>Simulasi suasana ujian.</h2><p>100 soal dari satu level, waktu 120 menit. Pembahasan dibuka setelah selesai. Timer tetap berjalan ketika halaman ditutup.</p></div>${button('Siapkan simulasi '+icon('arrow'),'setup','btn btn-dark', 'data-level="2" data-mode="exam"')}</section><div class="feature-row"><div>${icon('book')}<strong>Pembahasan setiap opsi</strong><p>Ketahui alasan benar dan salah.</p></div><div>${icon('bookmark')}<strong>Simpan yang penting</strong><p>Bookmark soal untuk diulang.</p></div><div>${icon('review')}<strong>Belajar dari kesalahan</strong><p>Soal sulit terkumpul otomatis.</p></div></div>`;}
function empty(title,desc){return `<div class="empty-state">${icon('seed')}<h3>${title}</h3><p>${desc}</p></div>`;}
function openDialog(html){const d=$('#dialog');d.innerHTML=`${button(icon('close'),'close-dialog','dialog-close icon-btn','aria-label="Tutup dialog"')}${html}`;if(!d.open)d.showModal();}
function setup(level=1,mode='practice'){
 openDialog(`<span class="eyebrow">SESUAIKAN RITME BELAJAR</span><h2>${mode==='exam'?'Simulasi ujian':'Sesi latihan baru'}</h2><p>${mode==='exam'?'Kunci dan pembahasan tersedia setelah ujian selesai.':'Pembahasan langsung tersedia setelah memeriksa jawaban.'}</p><form id="setup-form"><label>Level<select name="level">${LEVELS.map(l=>`<option value="${l.id}" ${l.id===level?'selected':''}>Level ${l.id} — ${l.name} (100 soal)</option>`).join('')}</select></label>${mode==='exam'?'<label>Durasi<select name="duration"><option value="120">120 menit</option><option value="90">90 menit</option><option value="60">60 menit</option></select></label><p class="form-help">100 soal dari seluruh bab, urutan diacak.</p>':`<label>Bab<select name="chapter"><option value="0">Semua bab</option>${CHAPTERS.map(c=>`<option value="${c.id}">${c.id}. ${c.short}</option>`).join('')}</select></label><label>Panjang sesi<select name="count"><option value="10">10 soal · Pemanasan</option><option value="25">25 soal · Sesi fokus</option><option value="100" selected>100 soal · Level lengkap</option></select></label><p class="form-help">Filter satu bab berisi 16–18 soal per level. Sesi memakai paling banyak jumlah yang tersedia.</p>`}<input type="hidden" name="mode" value="${mode}">${state.session&&!state.session.done?'<div class="warning-note">Memulai sesi baru mengganti sesi aktif. Jawaban latihan yang sudah diperiksa tetap tercatat; jawaban ujian yang belum selesai belum dinilai.</div>':''}<button class="btn btn-green full" type="submit">Mulai ${mode==='exam'?'ujian':'latihan'} ${icon('arrow')}</button></form>`);
}
function begin(ids,mode='practice',minutes=120){state.session={ids:Mining.shuffle(ids),mode,index:0,started:Date.now(),deadline:mode==='exam'?Date.now()+minutes*60000:null,choices:{},checked:{},flags:[],done:false,recorded:false};save();$('#dialog').close();navigate('session');}
function requestBegin(ids,mode='practice'){if(!ids.length){toast('Belum ada soal untuk sesi ini.');return;}if(state.session&&!state.session.done){openDialog(`<h2>Mulai sesi baru?</h2><p>Sesi aktif akan diganti. Progres latihan yang sudah diperiksa tetap tersimpan.</p>${button('Mulai sesi baru','confirm-custom','btn btn-green')}`);pendingStart={ids,mode};}else begin(ids,mode);}
let pendingStart=null;
function selectionFor(q){return state.session.choices[q.id];}
function optionMarkup(q,locked,reveal){const selected=selectionFor(q);return q.options.map((o,i)=>{const chosen=Array.isArray(selected)&&selected.includes(o.id);const result=reveal?(o.correct?'is-correct':chosen?'is-wrong':''):'';return `<button class="answer-option ${chosen?'chosen':''} ${result}" data-action="choose" data-option="${i}" aria-pressed="${chosen}" ${locked?'disabled':''}><span class="option-letter">${'ABCD'[i]}</span><span>${esc(o.text)}</span><span class="option-check">${reveal&&o.correct?icon('check'):reveal&&chosen?icon('close'):chosen?icon('check'):''}</span></button>`;}).join('')+`<button class="none-option ${Array.isArray(selected)&&selected.length===0?'chosen':''} ${reveal&&q.correct.length===0?'is-correct':''}" data-action="none" aria-pressed="${Array.isArray(selected)&&selected.length===0}" ${locked?'disabled':''}><span class="none-box">${Array.isArray(selected)&&!selected.length?icon('check'):''}</span>Tidak ada jawaban benar<span class="key-hint">0</span></button>`;}
function explanation(q,selected){const right=Mining.exact(selected,q.correct);return `<section class="explanation ${right?'correct':'incorrect'}" aria-live="polite"><div class="explanation-title">${icon(right?'check':'info')}<h3>${right?'Tepat. Konsepnya sudah nyambung!':selected==null?'Soal belum dijawab. Mari pahami.':'Belum tepat. Mari bongkar alasannya.'}</h3></div><p class="answer-key"><strong>Kunci:</strong> ${q.correct.length?q.correct.map(i=>'ABCD'[i]).join(', '):'Tidak ada jawaban benar'} <span>· Pilihanmu: ${selected==null?'Belum dijawab':selected.length?selected.map(i=>'ABCD'[i]).join(', '):'Tidak ada jawaban benar'}</span></p><p>${esc(q.explanation)}</p><div class="option-reasons">${q.options.map(o=>`<div><span class="reason-badge ${o.correct?'true':'false'}">${'ABCD'[o.id]} · ${o.correct?'Benar':'Salah'}</span><p>${esc(o.reason)}</p></div>`).join('')}</div>${sourceLink(q)}</section>`;}
function renderSession(){const s=state.session;if(!s)return `${heading('BELUM ADA SESI','Mulai dari <em>satu pertanyaan.</em>','Pilih level untuk memulai latihan.')}<a href="#practice" class="btn btn-green">Pilih level ${icon('arrow')}</a>`;if(s.done)return renderResults();
 const q=Q.get(s.ids[s.index]),selected=selectionFor(q),checked=!!s.checked[q.id],answered=Object.values(s.choices).filter(Array.isArray).length;const c=chapter(q.chapter);
 return `<div class="session-heading"><a href="#practice" class="text-link">← Kembali ke latihan</a><div>${s.mode==='exam'?`<span class="exam-timer">${icon('clock')}<strong id="exam-timer"></strong></span>`:'<span class="pill">'+(s.mode==='review'?'Ulangi & pahami':'Mode belajar')+'</span>'}${button(icon('flag')+(s.flags.includes(q.id)?'Ditandai':'Tandai'),'flag','btn btn-small '+(s.flags.includes(q.id)?'flagged':''))}</div></div><div class="session-progress"><div><strong>Soal ${s.index+1} <span>/ ${s.ids.length}</span></strong><span>${answered} terisi · ${s.ids.length-answered} belum diisi</span></div><div class="bar"><i style="width:${percent(answered,s.ids.length)}%"></i></div></div><div class="quiz-layout"><div><section class="question-card"><div class="question-tags"><span class="pill ${c.color}">Bab ${c.id} · ${c.short}</span><span class="pill">Level ${q.level} · ${LEVELS[q.level-1].name}</span>${button(icon('bookmark'),'bookmark','icon-btn '+(state.bookmarks.includes(q.id)?'bookmarked':''),`data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'Hapus':'Tambah'} bookmark" aria-pressed="${state.bookmarks.includes(q.id)}"`)}</div><span class="eyebrow question-topic">${esc(q.topic)}</span><h2>${esc(q.prompt)}</h2><p class="question-help">Pilih semua pernyataan yang benar. Bisa 0, 1, atau lebih dari satu.</p><div class="options">${optionMarkup(q,checked,checked)}</div><div class="question-bottom"><span>${Array.isArray(selected)?selected.length?selected.length+' opsi dipilih':'Tidak ada jawaban benar dipilih':'Belum dijawab'}</span>${s.mode==='exam'?button('Kosongkan jawaban','clear-choice','text-link',!Array.isArray(selected)?'disabled':''):checked?'<span class="checked-label">'+icon('check')+' Sudah diperiksa</span>':button('Periksa jawaban '+icon('arrow'),'check','btn btn-green',!Array.isArray(selected)?'disabled':'')}</div></section>${checked?explanation(q,selected):''}<div class="question-nav">${button('← Sebelumnya','prev','btn',s.index===0?'disabled':'')}${s.index<s.ids.length-1?button((checked||s.mode==='exam'?'Berikutnya':'Lewati dulu')+' '+icon('arrow'),'next','btn btn-green'):button('Selesaikan sesi '+icon('check'),'finish','btn btn-green')}</div><p class="keyboard-help">Pintasan: <kbd>1</kbd>–<kbd>4</kbd> pilih opsi · <kbd>0</kbd> tidak ada · <kbd>Enter</kbd> ${s.mode==='exam'?'lanjut':'periksa / lanjut'}</p></div><aside class="quiz-aside"><div class="paper-card"><div class="section-head compact"><h3>Navigasi soal</h3><span>${s.ids.length}</span></div><div class="question-map">${s.ids.map((id,i)=>{const a=s.choices[id],done=s.checked[id];return button(i+1,'jump','map-btn '+(i===s.index?'current ':'')+(done?(Mining.exact(a,Q.get(id).correct)?'right ':'wrong '):Array.isArray(a)?'answered ':'')+(s.flags.includes(id)?'marked':''),`data-index="${i}" aria-label="Soal ${i+1}${s.flags.includes(id)?', ditandai':''}" ${i===s.index?'aria-current="step"':''}`);}).join('')}</div><div class="map-legend"><span><i class="legend-dot"></i> Belum</span><span><i class="legend-dot filled"></i> Terisi</span><span><i class="legend-dot marked"></i> Ditandai</span></div>${button('Selesaikan sesi','finish','btn full')}</div><div class="source-note">${icon('info')}<p>${s.mode==='exam'?'Jawaban dapat diubah sampai ujian dikumpulkan. Pembahasan tidak ditampilkan selama ujian.':'Jawaban yang sudah diperiksa tidak bisa diubah dalam sesi ini. Kamu tetap dapat mengulangnya pada sesi baru.'}</p></div></aside></div>`;
}
function renderResults(){const s=state.session,score=s.ids.filter(id=>Mining.exact(s.choices[id],Q.get(id).correct)).length,blank=s.ids.filter(id=>!Array.isArray(s.choices[id])).length;
 return `${heading('SESI SELESAI','Setiap jawaban <em>jadi bekal.</em>','Lihat kembali alasan di balik jawabanmu, lalu ulangi konsep yang masih sulit.')}<section class="result-hero"><div class="score-ring" style="--score:${percent(score,s.ids.length)}%"><div><strong>${percent(score,s.ids.length)}<small>%</small></strong><span>KECOCOKAN PENUH</span></div></div><div><span class="eyebrow">${s.mode==='exam'?'SIMULASI UJIAN':'HASIL LATIHAN'}</span><h2>${score} dari ${s.ids.length} soal tepat.</h2><p>${s.ids.length-score} belum tepat, termasuk ${blank} soal tanpa jawaban.<br>Tidak memilih opsi hanya valid bila “Tidak ada jawaban benar” ditandai.</p><div class="button-row">${button('Ulangi yang belum tepat '+icon('review'),'retry-wrong','btn btn-green',score===s.ids.length?'disabled':'')}<a href="#practice" class="btn">Pilih level lain</a></div></div></section><div class="section-head"><h2>Pembahasan sesi</h2><span class="muted">${s.ids.length} soal</span></div><div class="result-list">${s.ids.map((id,i)=>{const q=Q.get(id),right=Mining.exact(s.choices[id],q.correct);return `<details class="result-item"><summary><span class="result-indicator ${right?'right':'wrong'}">${icon(right?'check':'close')}</span><span><small>SOAL ${i+1} · ${chapter(q.chapter).short}</small><strong>${esc(q.prompt)}</strong></span><span class="plus">+</span></summary><div class="result-body">${q.options.map(o=>`<p><strong>${'ABCD'[o.id]}.</strong> ${esc(o.text)}</p>`).join('')}${explanation(q,s.choices[id])}${button(icon('bookmark')+(state.bookmarks.includes(id)?' Tersimpan':' Simpan soal'),'bookmark','btn btn-small',`data-id="${id}"`)}</div></details>`;}).join('')}</div>`;
}
function reviewQuestions(){return QUESTIONS.filter(q=>reviewTab==='saved'?state.bookmarks.includes(q.id):state.attempts[q.id]&&!state.attempts[q.id].lastCorrect);}
function renderReview(){const qs=reviewQuestions();return `${heading('KESALAHAN ADALAH PETUNJUK','Ulangi yang sulit. <em>Rayakan yang paham.</em>','Daftar ini mengikuti jawaban terakhirmu. Soal keluar dari daftar sulit setelah dijawab tepat.')}<div class="toolbar"><div class="segmented">${button('Perlu diulang','review-tab','tab '+(reviewTab==='wrong'?'selected':''),'data-tab="wrong"')}${button(icon('bookmark')+' Tersimpan','review-tab','tab '+(reviewTab==='saved'?'selected':''),'data-tab="saved"')}</div>${button('Latih '+qs.length+' soal '+icon('arrow'),'review-all','btn btn-green',!qs.length?'disabled':'')}</div>${qs.length?`<div class="review-list">${qs.map(q=>`<article class="review-item"><span class="topic-icon ${chapter(q.chapter).color}">${icon(chapter(q.chapter).icon)}</span><div><span class="eyebrow">BAB ${q.chapter} · LEVEL ${q.level} · ${esc(q.topic)}</span><h3>${esc(q.prompt)}</h3><small>${state.attempts[q.id]?state.attempts[q.id].tries+' percobaan · '+state.attempts[q.id].right+' tepat':'Belum dicoba'}</small></div>${button('Latih '+icon('arrow'),'single-practice','btn btn-small',`data-id="${q.id}"`)}${button(icon('bookmark'),'bookmark','icon-btn '+(state.bookmarks.includes(q.id)?'bookmarked':''),`data-id="${q.id}" aria-label="Ubah bookmark"`)}</article>`).join('')}</div>`:empty(reviewTab==='saved'?'Belum ada soal tersimpan.':'Belum ada soal yang perlu diulang.',reviewTab==='saved'?'Klik ikon bookmark pada soal yang ingin kamu simpan.':'Mulai latihan. Soal yang belum tepat akan terkumpul di sini.')}`;}
function makeRecall(){recallQueue=Mining.shuffle(TOPICS.filter(t=>(!recallFilter||t.chapter===recallFilter)&&(!recallDueOnly||!state.recall[t.id]||state.recall[t.id].due<=Date.now())).map(t=>t.id));recallIndex=0;recallRevealed=false;}
function renderRecall(){const t=T.get(recallQueue[recallIndex]);return `${heading('INGAT TANPA MENGINTIP','Jeda sejenak. <em>Coba ingat kembali.</em>','Jelaskan konsep dengan bahasamu, buka jawabannya, lalu nilai seberapa mudah kamu mengingatnya.')}<div class="toolbar"><label class="inline-label">Bab<select id="recall-chapter"><option value="0">Semua bab</option>${CHAPTERS.map(c=>`<option value="${c.id}" ${recallFilter===c.id?'selected':''}>${c.short}</option>`).join('')}</select></label><label class="checkbox-label"><input type="checkbox" id="recall-due" ${recallDueOnly?'checked':''}> Hanya yang jatuh tempo / baru</label>${button('Acak ulang '+icon('review'),'recall-shuffle','btn btn-small')}</div>${t?`<div class="recall-meta"><span>Kartu ${recallIndex+1} dari ${recallQueue.length}</span><span>Bab ${t.chapter} · ${chapter(t.chapter).short}</span></div><section class="flashcard ${recallRevealed?'revealed':''}"><span class="topic-icon ${chapter(t.chapter).color}">${icon(chapter(t.chapter).icon)}</span><div class="eyebrow">${recallRevealed?'HUBUNGKAN DENGAN PENJELASANMU':'TANPA MEMBUKA CATATAN'}</div><h2>${esc(t.title)}</h2>${recallRevealed?`<p class="recall-answer">${esc(t.summary)}</p>${sourceLink(t)}`:`<p>Jelaskan idenya, berikan satu contoh,<br>dan sebutkan satu hal yang sering tertukar.</p>${button('Buka penjelasan '+icon('arrow'),'recall-reveal','btn btn-green')}<small>Tekan spasi untuk membuka</small>`}</section>${recallRevealed?`<div class="recall-grades"><p>Seberapa mudah kamu mengingatnya?</p><div>${button('Belum ingat <small>Ulangi dalam sesi ini</small>','recall-grade','recall-grade again','data-days="0"')}${button('Masih sulit <small>Besok</small>','recall-grade','recall-grade','data-days="1"')}${button('Cukup paham <small>3 hari lagi</small>','recall-grade','recall-grade','data-days="3"')}${button('Sudah lancar <small>7 hari lagi</small>','recall-grade','recall-grade easy','data-days="7"')}</div></div>`:'<p class="center muted">Tidak perlu sempurna. Usaha mengingat adalah bagian dari belajar.</p>'}`:`${empty('Sesi recall selesai.','Kartu yang dinilai dijadwalkan ulang berdasarkan tingkat pemahamanmu.')}<div class="center">${button('Mulai putaran baru','recall-shuffle','btn btn-green')}</div>`}<p class="recall-disclaimer">Jadwal pengulangan sederhana: 1, 3, atau 7 hari. Penilaian mandiri ini terpisah dari skor latihan soal.</p>`;}
function renderProgress(){const st=stats(),attempts=Object.values(state.attempts),total=attempts.reduce((n,a)=>n+a.tries,0),right=attempts.reduce((n,a)=>n+a.right,0);return `${heading('LIHAT PERKEMBANGANMU','Bukti kecil <em>dari proses belajarmu.</em>','Progres menghitung soal unik yang pernah dijawab dan ketepatan pada percobaan terakhir.')}<div class="stats-grid"><div class="stat-card"><span>Soal pernah dicoba</span><strong>${st.seen}<small>/300</small></strong><small>${300-st.seen} soal belum dicoba</small></div><div class="stat-card"><span>Jawaban terakhir tepat</span><strong>${st.mastered}<small>/300</small></strong><small>Ketepatan terbaru ${st.accuracy}%</small></div><div class="stat-card"><span>Total percobaan</span><strong>${total}</strong><small>${right} tepat · ${percent(right,total)}% seluruh percobaan</small></div><div class="stat-card"><span>Sesi selesai</span><strong>${state.history.length}</strong><small>${state.history.filter(h=>h.mode==='exam').length} simulasi ujian</small></div></div><div class="progress-layout"><section class="paper-card"><div class="section-head"><h2>Pemahaman per bab</h2></div>${CHAPTERS.map(c=>{const cs=stats(QUESTIONS.filter(q=>q.chapter===c.id)),n=QUESTIONS.filter(q=>q.chapter===c.id).length;return `<div class="chapter-progress"><div><span>${c.id}. ${c.short}</span><strong>${cs.mastered}/${n}</strong></div><div class="bar"><i style="width:${cs.pct}%"></i></div><small>${cs.seen} dicoba · ${cs.accuracy}% ketepatan terbaru pada yang dicoba</small></div>`;}).join('')}</section><section class="paper-card"><h2>Progres per level</h2>${LEVELS.map(l=>{const ss=stats(QUESTIONS.filter(q=>q.level===l.id));return `<div class="level-progress"><span class="topic-icon">${icon(l.icon)}</span><div><strong>${l.name}</strong><p>${ss.mastered} tepat dari 100 soal</p><div class="bar"><i style="width:${ss.pct}%"></i></div></div><span>${ss.pct}%</span></div>`;}).join('')}<div class="source-note">${icon('info')}<p>Ini indikator latihan, bukan prediksi nilai ujian. Periksa juga alasan jawaban dan kemampuan menjelaskan konsep.</p></div></section></div><section class="paper-card history"><div class="section-head"><h2>Riwayat sesi</h2><span class="muted">${state.history.length} selesai</span></div>${state.history.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Mode</th><th>Hasil</th><th>Skor</th></tr></thead><tbody>${state.history.slice(0,30).map(h=>`<tr><td>${esc(new Date(h.at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}))}</td><td>${h.mode==='exam'?'Simulasi':h.mode==='review'?'Pengulangan':'Latihan'}</td><td>${h.score} / ${h.total} tepat</td><td><span class="pill">${percent(h.score,h.total)}%</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Selesaikan satu sesi untuk melihat riwayat di sini.</p>'}</section><section class="backup-card"><div><h3>Progresmu, tetap milikmu.</h3><p>Data disimpan pada browser dan perangkat ini, tanpa sinkronisasi akun. Ekspor cadangan sebelum berganti perangkat atau menghapus data browser.</p></div><div class="button-row">${button(icon('download')+' Ekspor progres','export','btn')}${button(icon('upload')+' Impor cadangan','import','btn')}<input id="import-file" type="file" accept="application/json,.json" hidden></div></section>`;}
function render(){getRoute();if(route==='session'&&state.session?.mode==='exam'&&!state.session.done&&Date.now()>=state.session.deadline){Mining.finish(state,QUESTIONS);save();}shell();$('#main').innerHTML=({home:renderHome,library:renderLibrary,practice:renderPractice,session:renderSession,review:renderReview,recall:renderRecall,progress:renderProgress}[route])();document.title=({home:'Beranda',library:'Materi',practice:'Latihan',session:'Sesi',review:'Pengulangan',recall:'Recall',progress:'Progres'}[route])+' · Mining Mind';tick();}
function choose(index){const s=state.session;if(!s||s.done||s.checked[s.ids[s.index]])return;const id=s.ids[s.index],old=s.choices[id];const current=Array.isArray(old)?old:[];if(index===-1)s.choices[id]=[];else s.choices[id]=current.includes(index)?current.filter(x=>x!==index):[...current,index].sort();if(index!==-1&&!s.choices[id].length)delete s.choices[id];save();render();}
function check(){const s=state.session;if(!s||s.mode==='exam'||s.done)return;const q=Q.get(s.ids[s.index]);if(!Array.isArray(s.choices[q.id])||s.checked[q.id])return;Mining.record(state,q,s.choices[q.id]);s.checked[q.id]=true;save();render();$('.explanation')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function finishPrompt(){const s=state.session;if(!s||s.done)return;const n=s.ids.filter(id=>!Array.isArray(s.choices[id])).length;openDialog(`<span class="eyebrow">SELESAIKAN SESI</span><h2>Kumpulkan jawaban?</h2><p>${n?`Masih ada ${n} soal belum dijawab. Soal tersebut dihitung belum tepat, termasuk bila kuncinya tidak ada opsi benar.`:'Semua soal sudah terisi.'}</p><p>${s.mode==='exam'?'Setelah dikumpulkan, jawaban dikunci dan seluruh pembahasan dibuka.':'Jawaban terisi yang belum diperiksa akan dinilai saat sesi selesai.'}</p>${button('Kumpulkan & lihat hasil','confirm-finish','btn btn-green full')}`);}
function move(delta){const s=state.session;if(!s||s.done)return;const i=s.index+delta;if(i<0||i>=s.ids.length)return;s.index=i;save();render();window.scrollTo({top:0,behavior:'smooth'});}
function focusDialog(){const f=state.focus;openDialog(`<span class="eyebrow">SATU SESI, SATU FOKUS</span><h2>Ruang fokus 25 menit.</h2><p>Singkirkan distraksi, pilih satu bab, dan beri dirimu waktu untuk memahami. Timer fokus tidak memengaruhi timer ujian.</p><div class="focus-large" id="focus-large">${f?formatTime(f.until?Math.max(0,f.until-Date.now()):f.remaining):'25:00'}</div><div class="button-row">${button(f?.until?'Jeda':'Mulai / lanjutkan','focus-toggle','btn btn-green')}${button('Atur ulang','focus-reset','btn')}</div>`);}
function formatTime(ms){const n=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function tick(){const s=state.session;if(s?.mode==='exam'&&!s.done){const left=s.deadline-Date.now();if(left<=0){Mining.finish(state,QUESTIONS);save();$('#dialog').close();toast('Waktu ujian habis. Jawaban tersimpan sudah dikumpulkan.');render();return;}if($('#exam-timer'))$('#exam-timer').textContent=formatTime(left);}
 const f=state.focus;if(f){let left=f.until?Math.max(0,f.until-Date.now()):f.remaining;if(f.until&&left===0){state.focus={remaining:0,until:null};save();toast('Sesi fokus selesai. Ambil jeda sebentar.');}if($('#focus-label'))$('#focus-label').textContent=(f.until?'Fokus ':'Jeda ')+formatTime(left);if($('#focus-large'))$('#focus-large').textContent=formatTime(left);}}
document.addEventListener('click',e=>{if(e.target.closest('.sidebar a'))$('#sidebar').classList.remove('open');const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
 switch(a){
 case 'menu':$('#sidebar').classList.toggle('open');break;
 case 'close-dialog':$('#dialog').close();break;
 case 'quick-start':{const weak=stats().seen?CHAPTERS.map(c=>({id:c.id,pct:stats(QUESTIONS.filter(q=>q.chapter===c.id)).pct})).sort((a,b)=>a.pct-b.pct)[0].id:0;requestBegin(Mining.shuffle(QUESTIONS.filter(q=>q.level===1&&(!weak||q.chapter===weak)).map(q=>q.id)).slice(0,10));break;}
 case 'resume':navigate('session');break;
 case 'setup':setup(Number(el.dataset.level),el.dataset.mode);break;
 case 'confirm-custom':if(pendingStart){begin(pendingStart.ids,pendingStart.mode);pendingStart=null;}break;
 case 'chapter':search='';navigate('library/'+el.dataset.id);break;
 case 'topic-practice':requestBegin(QUESTIONS.filter(q=>q.topicId===el.dataset.id).map(q=>q.id));break;
 case 'single-practice':requestBegin([el.dataset.id],'review');break;
 case 'chapter-recall':recallFilter=Number(el.dataset.id);recallDueOnly=false;makeRecall();navigate('recall');break;
 case 'topic-recall':recallQueue=[el.dataset.id];recallIndex=0;recallRevealed=false;navigate('recall');break;
 case 'choose':choose(Number(el.dataset.option));break;
 case 'none':choose(-1);break;
 case 'clear-choice':delete state.session.choices[state.session.ids[state.session.index]];save();render();break;
 case 'check':check();break;
 case 'next':move(1);break;
 case 'prev':move(-1);break;
 case 'jump':state.session.index=Number(el.dataset.index);save();render();window.scrollTo({top:0,behavior:'smooth'});break;
 case 'flag':{const s=state.session,id=s.ids[s.index];s.flags=s.flags.includes(id)?s.flags.filter(x=>x!==id):[...s.flags,id];save();render();break;}
 case 'bookmark':{const id=el.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();const active=state.bookmarks.includes(id);el.classList.toggle('bookmarked',active);el.setAttribute('aria-pressed',String(active));el.setAttribute('aria-label',active?'Hapus bookmark':'Tambah bookmark');if(el.textContent.trim())el.innerHTML=icon('bookmark')+(active?' Tersimpan':' Simpan soal');if(route==='review')render();toast(active?'Soal disimpan.':'Bookmark dihapus.');break;}
 case 'finish':finishPrompt();break;
 case 'confirm-finish':Mining.finish(state,QUESTIONS);save();$('#dialog').close();render();window.scrollTo({top:0,behavior:'smooth'});break;
 case 'retry-wrong':requestBegin(state.session.ids.filter(id=>!Mining.exact(state.session.choices[id],Q.get(id).correct)),'review');break;
 case 'review-tab':reviewTab=el.dataset.tab;render();break;
 case 'review-all':requestBegin(reviewQuestions().map(q=>q.id),'review');break;
 case 'recall-shuffle':makeRecall();render();break;
 case 'recall-reveal':recallRevealed=true;render();break;
 case 'recall-grade':{const id=recallQueue[recallIndex],days=Number(el.dataset.days);state.recall[id]={due:Date.now()+days*86400000,reps:(state.recall[id]?.reps||0)+1,interval:days};if(days===0)recallQueue.push(id);recallIndex++;recallRevealed=false;save();render();break;}
 case 'focus':focusDialog();break;
 case 'focus-toggle':{let f=state.focus||{remaining:1500000,until:null};state.focus=f.until?{remaining:Math.max(0,f.until-Date.now()),until:null}:{remaining:f.remaining||1500000,until:Date.now()+(f.remaining||1500000)};save();focusDialog();tick();break;}
 case 'focus-reset':state.focus={remaining:1500000,until:null};save();focusDialog();tick();break;
 case 'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='mining-mind-progres-'+Mining.day()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Cadangan progres diunduh.');break;}
 case 'import':$('#import-file').click();break;
 case 'confirm-import':if(pendingImport){state=pendingImport;pendingImport=null;save();$('#dialog').close();render();toast('Cadangan berhasil dipulihkan.');}break;
 }
});
document.addEventListener('submit',e=>{if(e.target.id!=='setup-form')return;e.preventDefault();const f=new FormData(e.target),mode=f.get('mode'),level=Number(f.get('level')),ch=Number(f.get('chapter'));let qs=QUESTIONS.filter(q=>q.level===level&&(mode==='exam'||!ch||q.chapter===ch));const count=mode==='exam'?100:Number(f.get('count'));begin(Mining.shuffle(qs.map(q=>q.id)).slice(0,count),mode,Number(f.get('duration'))||120);});
let pendingImport=null;
document.addEventListener('change',async e=>{if(e.target.id==='recall-chapter'){recallFilter=Number(e.target.value);makeRecall();render();}if(e.target.id==='recall-due'){recallDueOnly=e.target.checked;makeRecall();render();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>5000000){toast('Cadangan terlalu besar (maksimal 5 MB).');return;}try{pendingImport=Mining.validate(JSON.parse(await file.text()),QUESTIONS,TOPICS);openDialog(`<h2>Pulihkan cadangan?</h2><p>Cadangan berisi ${Object.keys(pendingImport.attempts).length} soal pernah dicoba dan ${pendingImport.history.length} sesi selesai. Impor akan mengganti progres saat ini, termasuk sesi aktif.</p>${button('Ganti dengan cadangan ini','confirm-import','btn btn-green full')}`);}catch(err){toast('Impor dibatalkan: '+err.message);}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const pos=e.target.selectionStart;$('#main').innerHTML=renderLibrary();$('#search').focus();$('#search').setSelectionRange(pos,pos);}if(e.target.id==='chapter-note'){state.notes[libraryChapter]=e.target.value;save();$('#note-status').textContent='Tersimpan di browser ini.';}});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button,a')||$('#dialog').open||e.ctrlKey||e.metaKey||e.altKey)return;if(route==='session'&&state.session&&!state.session.done){if(/^[1-4]$/.test(e.key)){e.preventDefault();choose(Number(e.key)-1);}if(e.key==='0'){e.preventDefault();choose(-1);}if(e.key==='Enter'){e.preventDefault();const s=state.session;if(s.mode!=='exam'&&!s.checked[s.ids[s.index]])check();else if(s.index<s.ids.length-1)move(1);else finishPrompt();}}if(route==='recall'&&e.code==='Space'&&recallQueue[recallIndex]&&!recallRevealed){e.preventDefault();recallRevealed=true;render();}});
window.addEventListener('hashchange',()=>{$('#sidebar').classList.remove('open');if(location.hash==='#recall'&&!recallQueue.length)makeRecall();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===Mining.KEY)toast('Progres berubah di tab lain. Gunakan satu tab agar sesi tidak saling menimpa.');});
makeRecall();render();setInterval(tick,1000);if(storageWarning)toast('Progres tidak dapat dibaca. Data lama tidak dihapus; ekspor/cadangkan sebelum memulai ulang.');
